// ======================================================================
/*!
 * \brief Tests for datasets made of several PMTiles files
 *
 * The fixtures are generated by make_fixtures.py. Each tile contains the
 * text "<file> <z>/<x>/<y>" so that the tests can tell which file and tile
 * answered a request.
 */
// ======================================================================

#include "Config.h"
#include "TileStore.h"
#define BOOST_TEST_MODULE TileStoreTest
#include <boost/test/included/unit_test.hpp>
#include <filesystem>
#include <fstream>
#include <string>
#include <unistd.h>

using namespace SmartMet::Engine::OSM;

namespace
{
const std::filesystem::path data_dir = std::filesystem::absolute("data/osm");

// Write a configuration file and return its path
std::filesystem::path config_file(const std::filesystem::path& dir, const std::string& extra = "")
{
  auto path = std::filesystem::temp_directory_path() /
              ("osm_tilestore_" + std::to_string(::getpid()) + ".conf");
  std::ofstream out(path);
  out << "directory = \"" << dir.string() << "\";\n"
      << "min_file_age = 0;\n"
      << "rescan_interval = 0;\n"
      << extra;
  return path;
}

std::string content(const std::optional<Tile>& tile)
{
  if (!tile || !tile->data)
    return "none";
  return *tile->data;
}

struct Fixture
{
  Fixture() : conf(config_file(data_dir)), config(conf.string()), store(config) { store.rescan(); }
  ~Fixture() { std::filesystem::remove(conf); }

  std::filesystem::path conf;
  Config config;
  TileStore store;
};

}  // namespace

BOOST_AUTO_TEST_CASE(datasets_from_directory)
{
  Fixture f;
  auto names = f.store.datasets();
  BOOST_REQUIRE_EQUAL(names.size(), 2U);
  BOOST_CHECK_EQUAL(names[0], "basemap");
  BOOST_CHECK_EQUAL(names[1], "single");

  auto info = f.store.info("basemap");
  BOOST_REQUIRE(info);
  BOOST_CHECK_EQUAL(info->files.size(), 2U);
  BOOST_CHECK_EQUAL(info->minzoom, 0);
  BOOST_CHECK_EQUAL(info->maxzoom, 5);
  // The most detailed file comes first
  BOOST_CHECK_EQUAL(info->files[0].path.filename().string(), "region.pmtiles");
  BOOST_CHECK(info->metadata.find("region") != std::string::npos);

  BOOST_CHECK(!f.store.info("nosuchdataset"));
}

BOOST_AUTO_TEST_CASE(gzip_tiles_and_leaf_directories)
{
  Fixture f;
  // world.pmtiles has leaf directories of 8 entries
  BOOST_CHECK_EQUAL(content(f.store.getTile("single", 0, 0, 0)), "single 0/0/0");
  BOOST_CHECK_EQUAL(content(f.store.getTile("basemap", 2, 0, 3)), "world 2/0/3");
  BOOST_CHECK_EQUAL(content(f.store.getTile("basemap", 2, 3, 3)), "world 2/3/3");
  BOOST_CHECK_EQUAL(content(f.store.getTile("basemap", 2, 1, 2)), "world 2/1/2");
}

BOOST_AUTO_TEST_CASE(most_detailed_file_is_preferred)
{
  Fixture f;
  // The northeastern quadrant intersects the region
  BOOST_CHECK_EQUAL(content(f.store.getTile("basemap", 1, 1, 0)), "region 1/1/0");
  // Other quadrants come from the world file
  BOOST_CHECK_EQUAL(content(f.store.getTile("basemap", 1, 0, 0)), "world 1/0/0");
  BOOST_CHECK_EQUAL(content(f.store.getTile("basemap", 1, 1, 1)), "world 1/1/1");
}

BOOST_AUTO_TEST_CASE(ancestors_are_used_beyond_available_zoom)
{
  Fixture f;
  // Helsinki at zoom 10 comes from the zoom 5 tile of the region
  auto tile = f.store.getTile("basemap", 10, 581, 296);
  BOOST_REQUIRE(tile);
  BOOST_CHECK_EQUAL(content(tile), "region 5/18/9");
  BOOST_CHECK_EQUAL(tile->z, 5);
  BOOST_CHECK_EQUAL(tile->x, 18U);
  BOOST_CHECK_EQUAL(tile->y, 9U);

  // Outside the region the world file at zoom 2 is used
  tile = f.store.getTile("basemap", 4, 2, 10);
  BOOST_REQUIRE(tile);
  BOOST_CHECK_EQUAL(content(tile), "world 2/0/2");
  BOOST_CHECK_EQUAL(tile->z, 2);
}

BOOST_AUTO_TEST_CASE(invalid_requests)
{
  Fixture f;
  BOOST_CHECK(!f.store.getTile("nosuchdataset", 0, 0, 0));
  BOOST_CHECK(!f.store.getTile("basemap", 2, 4, 0));
  BOOST_CHECK(!f.store.getTile("basemap", 2, 0, 4));
  BOOST_CHECK(!f.store.getTile("basemap", 31, 0, 0));
}

BOOST_AUTO_TEST_CASE(cached_tiles_are_returned)
{
  Fixture f;
  auto t1 = f.store.getTile("basemap", 2, 1, 1);
  auto t2 = f.store.getTile("basemap", 2, 1, 1);
  BOOST_REQUIRE(t1 && t2);
  BOOST_CHECK_EQUAL(t1->data.get(), t2->data.get());
  BOOST_CHECK_EQUAL(f.store.tileCacheStats().hits, 1U);
}

BOOST_AUTO_TEST_CASE(rescan_detects_new_and_removed_files)
{
  // Copy the data so that it can be modified
  auto dir = std::filesystem::temp_directory_path() / ("osm_rescan_" + std::to_string(::getpid()));
  std::filesystem::remove_all(dir);
  std::filesystem::create_directories(dir / "basemap");
  std::filesystem::copy_file(data_dir / "basemap" / "world.pmtiles",
                             dir / "basemap" / "world.pmtiles");

  auto conf = config_file(dir);
  Config config(conf.string());
  TileStore store(config);
  store.rescan();

  auto info = store.info("basemap");
  BOOST_REQUIRE(info);
  BOOST_CHECK_EQUAL(info->maxzoom, 2);
  const auto version = info->version;
  BOOST_CHECK_EQUAL(content(store.getTile("basemap", 5, 18, 9)), "world 2/2/1");

  // Nothing changed
  store.rescan();
  BOOST_CHECK_EQUAL(store.info("basemap")->version, version);

  // A more detailed file appears
  std::filesystem::copy_file(data_dir / "basemap" / "region.pmtiles",
                             dir / "basemap" / "region.pmtiles");
  store.rescan();
  info = store.info("basemap");
  BOOST_CHECK_EQUAL(info->maxzoom, 5);
  BOOST_CHECK(info->version > version);
  BOOST_CHECK_EQUAL(content(store.getTile("basemap", 5, 18, 9)), "region 5/18/9");

  // A file which is not valid is ignored
  {
    std::ofstream out(dir / "basemap" / "broken.pmtiles");
    out << "not a pmtiles file";
  }
  store.rescan();
  BOOST_CHECK_EQUAL(store.info("basemap")->files.size(), 2U);

  // The detailed file disappears
  std::filesystem::remove(dir / "basemap" / "region.pmtiles");
  store.rescan();
  BOOST_CHECK_EQUAL(store.info("basemap")->maxzoom, 2);
  BOOST_CHECK_EQUAL(content(store.getTile("basemap", 5, 18, 9)), "world 2/2/1");

  std::filesystem::remove_all(dir);
  std::filesystem::remove(conf);
}

BOOST_AUTO_TEST_CASE(explicit_datasets)
{
  auto conf = config_file("/nonexistent",
                          "datasets: { mine: { files = [\"" +
                              (data_dir / "single.pmtiles").string() + "\"]; }; };\n");
  Config config(conf.string());
  TileStore store(config);
  store.rescan();
  auto names = store.datasets();
  BOOST_REQUIRE_EQUAL(names.size(), 1U);
  BOOST_CHECK_EQUAL(names[0], "mine");
  BOOST_CHECK_EQUAL(content(store.getTile("mine", 1, 1, 1)), "single 1/1/1");
  std::filesystem::remove(conf);
}
